css:
.bizmodelsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1d2433;
    background: linear-gradient(160deg, #f3f1ea 0%, #eae5d8 100%);
    border-radius: 18px;
}

.bizmodelsim-container * {
    box-sizing: border-box;
}

.bizmodelsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #11203a 0%, #1c3358 55%, #2a4a7a 100%);
    color: #f5f1e6;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(17, 32, 58, 0.32);
}

.bizmodelsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.bizmodelsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e2c277;
    background: rgba(226, 194, 119, 0.14);
    padding: 5px 14px;
    border-radius: 999px;
}

.bizmodelsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dfe4ee;
}

.bizmodelsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2a3c5e;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.bizmodelsim-period-counter #currentDay,
.bizmodelsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #11203a;
}

.bizmodelsim-round-name {
    background: #dce5f2;
    color: #11203a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.bizmodelsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a4a16;
    background: #f6e4d0;
    padding: 4px 12px;
    border-radius: 999px;
}

.bizmodelsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.bizmodelsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e3dcc8;
    box-shadow: 0 4px 14px rgba(17, 32, 58, 0.07);
    border-top: 4px solid #2a4a7a;
}

.bizmodelsim-card-coherence { border-top-color: #b8902f; }
.bizmodelsim-card-confidence { border-top-color: #2a4a7a; }
.bizmodelsim-card-runway { border-top-color: #1f7a55; }
.bizmodelsim-card-budget { border-top-color: #6a4fb0; }

.bizmodelsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6c7488;
}

.bizmodelsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #11203a;
}

.bizmodelsim-card-coherence .bizmodelsim-value { color: #a87f1f; }
.bizmodelsim-card-confidence .bizmodelsim-value { color: #2a4a7a; }
.bizmodelsim-card-runway .bizmodelsim-value { color: #1f7a55; }
.bizmodelsim-card-budget .bizmodelsim-value { color: #6a4fb0; }

.bizmodelsim-sublabel {
    font-size: 0.76rem;
    color: #7c849a;
    line-height: 1.35;
}

.bizmodelsim-coherence-low .bizmodelsim-value { color: #c0392b; }
.bizmodelsim-coherence-strong .bizmodelsim-value { color: #1f7a55; }

.bizmodelsim-confidence-approve .bizmodelsim-value { color: #1f7a55; }
.bizmodelsim-confidence-block .bizmodelsim-value { color: #c0392b; }

.bizmodelsim-runway-out { border-top-color: #c0392b; }
.bizmodelsim-runway-out .bizmodelsim-value { color: #c0392b; }

.bizmodelsim-budget-over { border-top-color: #c0392b; }
.bizmodelsim-budget-over .bizmodelsim-value { color: #c0392b; }

.bizmodelsim-runway-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #11203a;
    color: #eef1f7;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.bizmodelsim-runway-bar #runwayBarDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e2c277;
}

.bizmodelsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #b8902f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(17, 32, 58, 0.06);
}

.bizmodelsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.bizmodelsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #11203a;
    margin-bottom: 6px;
}

.bizmodelsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #303a50;
}

.bizmodelsim-briefing-text strong { color: #1f7a55; }
.bizmodelsim-briefing-text em { color: #9a4a16; font-style: italic; }

.bizmodelsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e3dcc8;
    box-shadow: 0 4px 14px rgba(17, 32, 58, 0.07);
}

.bizmodelsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #11203a;
    border-bottom: 2px solid #efe9da;
    padding-bottom: 8px;
}

.bizmodelsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #25304a;
    margin: 14px 0 6px;
}

.bizmodelsim-container select,
.bizmodelsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cfc7b0;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #faf8f1;
    color: #1d2433;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.bizmodelsim-container select:focus,
.bizmodelsim-container input[type="number"]:focus {
    outline: none;
    border-color: #b8902f;
    box-shadow: 0 0 0 3px rgba(184, 144, 47, 0.18);
}

.bizmodelsim-container select option {
    background-color: #ffffff;
    color: #1d2433;
}

.bizmodelsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #b8902f;
}

.bizmodelsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2a4a7a;
    margin-top: 4px;
}

.bizmodelsim-range-readout span:nth-child(2) {
    color: #a87f1f;
    font-weight: 800;
}

.bizmodelsim-hint {
    font-size: 0.8rem;
    color: #7c849a;
    margin-top: 4px;
    line-height: 1.4;
}

.bizmodelsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.bizmodelsim-container .btn-primary {
    background: linear-gradient(135deg, #11203a 0%, #2a4a7a 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #ffffff;
    box-shadow: 0 6px 16px rgba(17, 32, 58, 0.28);
}

.bizmodelsim-container .btn-primary:hover {
    filter: brightness(1.12);
}

.bizmodelsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cfc7b0;
    color: #6c7488;
}

.bizmodelsim-coach {
    background: #11203a;
    color: #eef1f7;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(17, 32, 58, 0.24);
}

.bizmodelsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e2c277;
    margin-bottom: 8px;
}

.bizmodelsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.bizmodelsim-coach-body strong { color: #f0d489; }
.bizmodelsim-coach-body em { color: #f1b48f; font-style: italic; }

.bizmodelsim-history,
.bizmodelsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e3dcc8;
    box-shadow: 0 4px 14px rgba(17, 32, 58, 0.07);
}

.bizmodelsim-history h3,
.bizmodelsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #11203a;
}

.bizmodelsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #25304a;
}

.bizmodelsim-container table#usfHistoryTable th {
    background: #f0ece0;
    color: #11203a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e3dcc8;
}

.bizmodelsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f2eee3;
}

.bizmodelsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf8f1;
}

.bizmodelsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .bizmodelsim-container {
        padding: 14px;
    }
    .bizmodelsim-header h1 {
        font-size: 1.7rem;
    }
    .bizmodelsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .bizmodelsim-value {
        font-size: 2rem;
    }
    .bizmodelsim-clock {
        margin-left: 0;
    }
    .bizmodelsim-period-counter {
        font-size: 0.88rem;
    }
    .bizmodelsim-runway-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .bizmodelsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion message (formatCompletionMessage) */
.bizmodelsim-completion { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #11203a; }
.bizmodelsim-cm-head { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; padding-bottom: 14px; border-bottom: 1px solid rgba(17,32,58,0.14); margin-bottom: 16px; }
.bizmodelsim-cm-score { font-size: 46px; font-weight: 800; line-height: 1; color: #1f7a55; }
.bizmodelsim-cm-score-max { font-size: 18px; font-weight: 600; color: #2a4a7a; margin-left: 2px; }
.bizmodelsim-cm-grade { font-size: 18px; font-weight: 700; color: #11203a; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.bizmodelsim-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; letter-spacing: .02em; padding: 3px 10px; border-radius: 999px; }
.bizmodelsim-cm-yes { background: rgba(31,122,85,0.15); color: #175d40; }
.bizmodelsim-cm-no { background: rgba(192,57,43,0.12); color: #b03325; }
.bizmodelsim-cm-warn { background: rgba(180,120,20,0.16); color: #8a5c10; }
.bizmodelsim-cm-metrics { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 18px; }
.bizmodelsim-cm-metric { flex: 1 1 130px; background: #f2efe6; border: 1px solid rgba(17,32,58,0.10); border-radius: 10px; padding: 12px 14px; text-align: center; }
.bizmodelsim-cm-mv { display: block; font-size: 22px; font-weight: 800; color: #11203a; }
.bizmodelsim-cm-ml { display: block; font-size: 12px; font-weight: 600; color: #2a4a7a; margin-top: 2px; }
.bizmodelsim-cm-insights-title { font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: #2a4a7a; margin-bottom: 8px; }
.bizmodelsim-cm-insights { margin: 0; padding-left: 20px; }
.bizmodelsim-cm-insights li { font-size: 14px; line-height: 1.5; color: #22314a; margin-bottom: 8px; }

