                budgetSpend += d.invest;
                cashSpend += d.invest * 1000;
                const invMiss = this._outside(d.invest, P.invest);
                if (invMiss === 0) { coherenceDelta += 6; confidenceDelta += 4; }
                else {
                    const pen = Math.min(12, Math.round(invMiss / 45));
                    coherenceDelta -= pen; confidenceDelta -= Math.round(pen * 0.8);
                    if (d.invest < P.invest[0]) coachKey = `coach_r3_underinvest`;
                    else coachKey = `coach_r3_overinvest`;
                }

                // The conversion bet, judged against a band you only know if you paid for it.
                const convMiss = this._outside(d.conversion, P.conv);
                if (convMiss === 0) { confidenceDelta += 7; coherenceDelta += 4; }
                else {
                    const mult = (ds.research === `full`) ? 0.6 : (ds.research === `light`) ? 0.85 : 1.4;
                    const pen = Math.min(16, Math.round((convMiss / 2) * mult));
                    confidenceDelta -= pen;
                    coherenceDelta -= Math.round(pen * 0.4);
                    if (d.conversion > P.conv[1]) coachKey = `coach_r3_overconvert`;
                }

                summaryKey = (invMiss === 0 && convMiss === 0) ? `sum_r3_good` : `sum_r3_weak`;

            } else if (round === 4) {
                // Operations, all strategy-relative. Keeping the plant is right for craft and
                // fatal for a platform. Hiring product engineers is right for a platform and
                // wrong for craft.
                coherenceDelta += this._fit(P.plant, d.plant);
                confidenceDelta += Math.round(this._fit(P.plant, d.plant) * 0.7);
                ds.plantResolved = true;
                ds.plantHalf = (d.plant === `reconfigure`);
                if (d.plant === `closeall`) { cashSpend += this.CLOSE_COST; }
                if (d.plant === `leaseback`) { cashSpend -= this.LEASEBACK_CASH; ds.rent = this.LEASEBACK_RENT; }
                if (d.plant === `keep`) { ds.plantResolved = false; }

                coherenceDelta += this._fit(P.team, d.team);
                confidenceDelta += Math.round(this._fit(P.team, d.team) * 0.6);

                // Retaining the two designers is no longer a free +5. It costs real cash from
                // the same runway that funds the pivot.
                const desFit = this._fit(P.designers, d.designers);
                coherenceDelta += desFit;
                confidenceDelta += Math.round(desFit * 0.9);
                if (d.designers === `retain`) { cashSpend += this.DESIGNER_RETENTION; coachKey = `coach_r4_retaincost`; }
                else { ds.designersLost = true; coachKey = (d.designers === `hope`) ? `coach_r4_hope` : `coach_r4_release`; }

                // Two cost bases fighting inside one P&L.
                if (d.plant === `keep` && d.team === `hireproduct`) {
                    coherenceDelta -= 7; confidenceDelta -= 6; coachKey = `coach_r4_twocostbases`;
                }
                if (this._fit(P.plant, d.plant) > 0 && this._fit(P.team, d.team) > 0) {
                    coachKey = `coach_r4_coherent_` + S;
                }

                summaryKey = `sum_r4_` + S;

            } else if (round === 5) {
                // The pitch is checked against what the learner actually built. Claiming a
                // coherent model you do not have is now punished rather than rewarded.
                if (d.pitch === `coherent`) {
                    if (ds.coherence >= 55) { coherenceDelta += 7; confidenceDelta += 11; coachKey = `coach_r5_coherent`; }
                    else { confidenceDelta -= 9; coachKey = `coach_r5_overclaim`; }
                } else if (d.pitch === `tradeoff`) {
                    coherenceDelta += 4; confidenceDelta += 8; coachKey = `coach_r5_tradeoff`;
                } else if (d.pitch === `vision`) {
                    // A vision pitch is the right instrument for a platform bet and the wrong
                    // one for anything you have promised to fund inside fourteen months.
                    if (S === `platform` && d.invest >= 480) { coherenceDelta += 2; confidenceDelta += 7; coachKey = `coach_r5_vision_platform`; }
                    else { coherenceDelta -= 5; confidenceDelta -= 8; coachKey = `coach_r5_vision`; }
                } else if (d.pitch === `bolton`) {
                    coherenceDelta -= 10; confidenceDelta -= 14; coachKey = `coach_r5_bolton`;
                }

                // The honest risk depends on the state the learner has actually created.
                const lowRunway = ds.runway < 500000;
                const stretchedConv = this._outside(d.conversion, P.conv) > 0 && d.conversion > P.conv[1];
                const thinCapacity = (S === `service` && d.team !== `retrain`) || ds.designersLost;
                let riskRight = `conversion`;
                if (lowRunway) riskRight = `runway`;
                else if (thinCapacity) riskRight = `capacity`;
                else if (stretchedConv) riskRight = `conversion`;
                else riskRight = (S === `platform`) ? `adoption` : `conversion`;

                if (d.risk === `none`) { confidenceDelta -= 12; coachKey = `coach_r5_risknone`; }
                else if (d.risk === riskRight) { confidenceDelta += 8; coherenceDelta += 3; coachKey = `coach_r5_riskright`; }
                else { confidenceDelta += 1; coachKey = `coach_r5_riskwrong`; }

                // Margin band is strategy-specific: craft defends a high margin, a platform
                // cannot and should not claim one.
                const mMiss = this._outside(d.margin, P.margin);
                if (mMiss === 0) { confidenceDelta += 5; coherenceDelta += 2; }
                else {
                    confidenceDelta -= Math.min(10, Math.round(mMiss * 1.2));
                    if (d.margin > P.margin[1]) coachKey = `coach_r5_overmargin`;
                }

                confidenceDelta += Math.round((d.conviction - 60) / 9);
                if (ds.insolvent) { confidenceDelta -= 10; }
                summaryKey = `sum_r5_` + S;
            }

            // Resource accounting.
            ds.budgetUsed = Math.min(this.BUDGET_CAP, Math.round(ds.budgetUsed + budgetSpend));
            ds.runway = Math.max(0, Math.round(ds.runway - cashSpend));
            if (ds.runway <= 0) { ds.insolvent = true; }

            ds.coherence = Math.max(0, Math.min(100, ds.coherence + coherenceDelta));
            ds.confidence = Math.max(0, Math.min(100, ds.confidence + confidenceDelta));

            if (ds.insolvent) {
                ds.confidence = Math.max(0, Math.min(ds.confidence, 25));
                coachKey = `coach_insolvent`;
            }

            // The board blocks a final model that is incoherent or has lost their confidence.
            if (round === this.ROUNDS.length) {
                if (ds.confidence < this.APPROVE_THRESHOLD || ds.coherence < 55 || ds.insolvent) ds.boardBlocked = true;
            }

            ds.coherenceHistory.push(Math.round(ds.coherence));
            ds.confidenceHistory.push(Math.round(ds.confidence));
            ds.runwayHistory.push(Math.round(ds.runway / 10000));

            // v1.1.0: publish composite (0-100) to the reporting/grading layer every period.
            ds.performance = { overallScore: this._composite(ds) };

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            return {
                period: state.currentPeriod,
                strategy: S,
                coherence: Math.round(ds.coherence),
                coherenceDelta: Math.round(coherenceDelta),
                confidence: Math.round(ds.confidence),
                confidenceDelta: Math.round(confidenceDelta),
                runway: Math.round(ds.runway),
                budgetUsed: ds.budgetUsed,
                insolvent: ds.insolvent,
                boardBlocked: ds.boardBlocked,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }


        _money(eur) {
            // Locale-aware EUR formatter. EN: €1.80M / €450k. ES: 1,80 M€ / 450k €.
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Number(eur) || 0;
            if (lang === `es`) {
                if (Math.abs(n) >= 1000000) return (n / 1000000).toFixed(2).replace(`.`, `,`) + ` M€`;
                return Math.round(n / 1000) + `k €`;
            }
            if (Math.abs(n) >= 1000000) return `€` + (n / 1000000).toFixed(2) + `M`;
            return `€` + Math.round(n / 1000) + `k`;
        }

