            if (ds.insolvent) return window.mySimulation.t(`hint_insolvent`);
            if (ds.runway < 350000 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_cash`);
            if (ds.coherence < 40) return window.mySimulation.t(`hint_coherence`);
            if (state.currentPeriod >= 3 && ds.confidence < 45) return window.mySimulation.t(`hint_confidence`);
            if (ds.coherence >= 70 && ds.confidence >= this.APPROVE_THRESHOLD) return window.mySimulation.t(`hint_strong`);
            return null;
        }

